package provider

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/darshan-rambhia/terraform-provider-docker-compose/internal/ssh"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/booldefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/int64default"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringdefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

// Ensure provider defined types fully satisfy framework interfaces.
var _ resource.Resource = &StackResource{}
var _ resource.ResourceWithImportState = &StackResource{}

func NewStackResource() resource.Resource {
	return &StackResource{
		sshClientFactory: DefaultSSHClientFactory,
	}
}

// SSHClientFactory is a function type that creates SSH clients.
type SSHClientFactory func(config ssh.Config) (ssh.ClientInterface, error)

// DefaultSSHClientFactory creates real SSH clients.
var DefaultSSHClientFactory SSHClientFactory = func(config ssh.Config) (ssh.ClientInterface, error) {
	return ssh.NewClient(config)
}

// StackResource defines the resource implementation.
type StackResource struct {
	providerConfig   *DockerComposeProviderModel
	sshClientFactory SSHClientFactory
}

// StackResourceModel describes the resource data model.
type StackResourceModel struct {
	// Required.
	Host       types.String `tfsdk:"host"`
	RemotePath types.String `tfsdk:"remote_path"`
	Content    types.String `tfsdk:"content"`

	// Optional - connection settings (override provider defaults).
	SSHUser            types.String `tfsdk:"ssh_user"`
	SSHPrivateKey      types.String `tfsdk:"ssh_private_key"`
	SSHKeyPath         types.String `tfsdk:"ssh_key_path"`
	SSHPort            types.Int64  `tfsdk:"ssh_port"`
	SSHPassword        types.String `tfsdk:"ssh_password"`
	SSHCertificate     types.String `tfsdk:"ssh_certificate"`
	SSHCertificatePath types.String `tfsdk:"ssh_certificate_path"`

	// Optional - bastion/jump host settings.
	BastionHost     types.String `tfsdk:"bastion_host"`
	BastionPort     types.Int64  `tfsdk:"bastion_port"`
	BastionUser     types.String `tfsdk:"bastion_user"`
	BastionKey      types.String `tfsdk:"bastion_private_key"`
	BastionKeyPath  types.String `tfsdk:"bastion_key_path"`
	BastionPassword types.String `tfsdk:"bastion_password"`

	// Optional - security settings.
	InsecureIgnoreHostKey types.Bool `tfsdk:"insecure_ignore_host_key"`

	// Optional - lifecycle settings.
	Up       types.Bool `tfsdk:"up"`
	Validate types.Bool `tfsdk:"validate"`

	// Computed.
	ID          types.String `tfsdk:"id"`
	ContentHash types.String `tfsdk:"content_hash"`
}

func (r *StackResource) Metadata(ctx context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_stack"
}

func (r *StackResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: `
Manages a Docker Compose stack on a remote host via SSH.

## Behavior

- **Create**: Uploads compose file, optionally validates, optionally runs 'docker compose up -d'
- **Read**: Retrieves remote file hash for drift detection
- **Update**: If content changes, runs 'docker compose down' (if up=true), uploads new file, runs 'docker compose up -d'
- **Delete**: Runs 'docker compose down', removes compose file

## Important Notes

package ssh

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/darshan-rambhia/gosftp"
	"golang.org/x/crypto/ssh"
	"golang.org/x/crypto/ssh/knownhosts"
)

// AuthMethod represents the SSH authentication method to use.
type AuthMethod string

const (
	// AuthMethodPrivateKey uses SSH private key authentication (default).
	AuthMethodPrivateKey AuthMethod = "private_key"
	// AuthMethodPassword uses password authentication.
	AuthMethodPassword AuthMethod = "password"
	// AuthMethodCertificate uses SSH certificate authentication.
	AuthMethodCertificate AuthMethod = "certificate"
)

// Config holds SSH connection configuration.
type Config struct {
	Host string
	Port int
	User string

	// Authentication method (defaults to private_key if not specified).
	AuthMethod AuthMethod

	// Private key authentication.
	PrivateKey string // Key content (PEM encoded)
	KeyPath    string // Path to key file

	// Password authentication.
	Password string

	// Certificate authentication.
	Certificate     string // Certificate content
	CertificatePath string // Path to certificate file

	// Connection options.
	Timeout time.Duration // Connection timeout (default 30s)

	// Host key verification.
	KnownHostsFile        string // Path to known_hosts file
	InsecureIgnoreHostKey bool   // Skip host key verification (DANGEROUS)

	// Bastion/Jump host configuration for multihop SSH.
	BastionHost     string
	BastionPort     int
	BastionUser     string
	BastionKey      string // Private key content for bastion
	BastionKeyPath  string // Path to private key for bastion
	BastionPassword string // Password for bastion (if using password auth)
}

// ClientInterface defines the interface for SSH/SFTP operations.
type ClientInterface interface {
	Close() error
	UploadFile(ctx context.Context, localPath, remotePath string) error
	UploadContent(ctx context.Context, content []byte, remotePath string) error
	GetFileHash(ctx context.Context, remotePath string) (string, error)
	SetFileAttributes(ctx context.Context, remotePath, owner, group, mode string) error
	DeleteFile(ctx context.Context, remotePath string) error
	FileExists(ctx context.Context, remotePath string) (bool, error)
	GetFileInfo(ctx context.Context, remotePath string) (os.FileInfo, error)
	ReadFileContent(ctx context.Context, remotePath string, maxBytes int64) ([]byte, error)
	RunCommand(ctx context.Context, command string) (stdout string, stderr string, err error)
}

// Client wraps gosftp and SSH connections for file operations.
type Client struct {
	gosftpClient *gosftp.Client
	sshClient    *ssh.Client
	config       Config
}

var _ ClientInterface = (*Client)(nil)

// NewClient creates a new SSH/SFTP client using gosftp.
func NewClient(config Config) (*Client, error) {
	gosftpConfig := gosftp.Config{
		Host:                  config.Host,
		Port:                  config.Port,
		User:                  config.User,
		AuthMethod:            gosftp.AuthMethod(config.AuthMethod),
		PrivateKey:            config.PrivateKey,
		KeyPath:               config.KeyPath,
		Password:              config.Password,
		Certificate:           config.Certificate,
		CertificatePath:       config.CertificatePath,

