package provider

import (
	"context"
	"errors"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func TestStackResource_Metadata(t *testing.T) {
	t.Parallel()

	r := NewStackResource()
	req := resource.MetadataRequest{ProviderTypeName: "remote_docker_compose_file"}
	resp := &resource.MetadataResponse{}

	r.Metadata(context.Background(), req, resp)

	if resp.TypeName != "remote_docker_compose_file_stack" {
		t.Errorf("Metadata() TypeName = %q, want %q", resp.TypeName, "remote_docker_compose_file_stack")
	}
}

func TestStackResource_Schema(t *testing.T) {
	t.Parallel()

	r := NewStackResource()
	req := resource.SchemaRequest{}
	resp := &resource.SchemaResponse{}

	r.Schema(context.Background(), req, resp)

	if resp.Diagnostics.HasError() {
		t.Errorf("Schema() returned errors: %v", resp.Diagnostics)
	}

	// Verify required attributes exist
	requiredAttrs := []string{"host", "remote_path", "content"}
	for _, attr := range requiredAttrs {
		if _, ok := resp.Schema.Attributes[attr]; !ok {
			t.Errorf("Schema() missing required attribute %q", attr)
		}
	}

	// Verify optional attributes exist
	optionalAttrs := []string{"ssh_user", "ssh_key_path", "ssh_port", "up", "validate", "bastion_host"}
	for _, attr := range optionalAttrs {
		if _, ok := resp.Schema.Attributes[attr]; !ok {
			t.Errorf("Schema() missing optional attribute %q", attr)
		}
	}

	// Verify computed attributes exist
	computedAttrs := []string{"id", "content_hash"}
	for _, attr := range computedAttrs {
		if _, ok := resp.Schema.Attributes[attr]; !ok {
			t.Errorf("Schema() missing computed attribute %q", attr)
		}
	}
}

func TestHashContent(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		content string
	}{
		{
			name:    "simple content",
			content: "version: '3.8'",
		},
		{
			name:    "empty content",
			content: "",
		},
		{
			name: "multiline content",
			content: `version: '3.8'
services:
  nginx:
    image: nginx:alpine
    ports:
      - "80:80"`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			hash := hashContent(tt.content)

			// Verify hash format
			if len(hash) < 10 || hash[:7] != "sha256:" {
				t.Errorf("hashContent() = %q, expected sha256: prefix", hash)
			}

			// Verify determinism
			hash2 := hashContent(tt.content)
			if hash != hash2 {
				t.Errorf("hashContent() not deterministic: %q != %q", hash, hash2)
			}
		})
	}
}

func TestHashContent_Uniqueness(t *testing.T) {
	t.Parallel()

	content1 := "version: '3.8'"
	content2 := "version: '3.9'"

	hash1 := hashContent(content1)
	hash2 := hashContent(content2)

	if hash1 == hash2 {
		t.Error("hashContent() should produce different hashes for different content")
	}
}

func TestStackResource_GetSSHConfig(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name            string
		data            *StackResourceModel
		providerConfig  *DockerComposeProviderModel
		wantHost        string
		wantUser        string
		wantPort        int
		wantPassword    string
		wantBastionHost string
		wantBastionPort int
		wantBastionUser string
		wantInsecure    bool
		wantCert        string
		wantCertPath    string
	}{
		// Basic config tests
		{
			name: "basic config from resource",
			data: &StackResourceModel{
				Host:    types.StringValue("192.168.1.100"),
				SSHUser: types.StringValue("deploy"),

package ssh

import (
	"os"
	"path/filepath"
	"testing"
)

func TestExpandPath(t *testing.T) {
	t.Parallel()

	homeDir, err := os.UserHomeDir()
	if err != nil {
		t.Fatalf("failed to get home directory: %v", err)
	}

	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "path with tilde",
			input:    "~/test/path",
			expected: filepath.Join(homeDir, "test/path"),
		},
		{
			name:     "absolute path",
			input:    "/absolute/path",
			expected: "/absolute/path",
		},
		{
			name:     "relative path",
			input:    "relative/path",
			expected: "relative/path",
		},
		{
			name:     "empty path",
			input:    "",
			expected: "",
		},
		{
			name:     "tilde only",
			input:    "~",
			expected: "~",
		},
		{
			name:     "tilde with slash only",
			input:    "~/",
			expected: homeDir,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			result := ExpandPath(tt.input)
			if result != tt.expected {
				t.Errorf("ExpandPath(%q) = %q, want %q", tt.input, result, tt.expected)
			}
		})
	}
}

func TestShellQuote(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "simple string",
			input:    "hello",
			expected: "'hello'",
		},
		{
			name:     "string with spaces",
			input:    "hello world",
			expected: "'hello world'",
		},
		{
			name:     "string with single quote",
			input:    "it's",
			expected: "'it'\"'\"'s'",
		},
		{
			name:     "empty string",
			input:    "",
			expected: "''",
		},
		{
